prompt:
Create unit `tasks` and implement `reverse_into`: for dst and src of equal length, write src in reverse order into dst (dst[k] == src[src.len() - 1 - k]). The contract must state this for every index.

Required signature (in unit `tasks`):
fn reverse_into(dst: &mut [i64], src: &[i64]) -> ()

reference.code:
spec fn rev_below(dst: &[i64], src: &[i64], n: usize) -> bool { forall|k: usize| k < n ==> #[trigger] dst[k] == src[src.len() - 1 - k] }

spec fn reversed(dst: &[i64], src: &[i64]) -> bool { dst.len() == src.len() && (forall|k: usize| k < dst.len() ==> #[trigger] dst[k] == src[src.len() - 1 - k]) }

#[effects(pure)]
#[uses(u3::d032, rev_below, reversed)]
fn reverse_into(dst: &mut [i64], src: &[i64]) -> ()
    requires u3::d032(dst, src),
    ensures reversed(dst, src),
{
    let mut k: usize = 0;
    while k < dst.len()
        invariant k <= dst.len(), dst.len() == src.len(), rev_below(dst, src, k),
        decreases dst.len() - k,
    {
        dst[k] = src[src.len() - 1 - k];
        k = k + 1;
    }
}

